With(
    {
        _registro: Self.LastSubmit,
        _aeroporto: Self.LastSubmit.IATA & " - " & Self.LastSubmit.Aeroporto
    },
    If(
        // B1 - iniciar um acionamento PRAI caía no ramo "else" (o de
        // finalizar): gravava FINALIZAÇÃO imediata e notificava
        // "finalizado com sucesso". O início vale para PLEM e PRAI.
        var_acaoFormOcorrenciaAcionamento = "Iniciar",
        //---------------------------------------------------------
// ATUALIZA PROTOCOLO
//---------------------------------------------------------
        Patch(
            tbl_ocorrenciaAcionamento,
            _registro,
            {Protocolo: _registro.IATA & "-ACI-" & Coalesce(_registro.Acionamento, "PLEM") & "-" & _registro.ID}
        );
        UpdateContext({var_visibleConfigFluxo: true});
        //---------------------------------------------------------
        // CARREGA FLUXOGRAMA
        //---------------------------------------------------------
        ClearCollect(
            col_emergenciaFluxo,
            Filter(
                tbl_FluxogramaAcionamentos,
                Aeroporto = _registro.Aeroporto && ID_emergencia = var_dadosEmergencia.ID
            )
        );
        //---------------------------------------------------------
        // MONTA PARTICIPANTES
        //---------------------------------------------------------
        /*ClearCollect(
            col_emailsCcrFilter;
            Filter(
                tbl_EntidadeContatoRelacionamento;
                ID_emergencia = 536 &&
                EndsWith(
                    Lower(email);
                    "@motiva.com.br"
                )
            )
        );;*/Clear(col_emailsCcrFilter);
        Collect(
            col_emailsCcrFilter,
            ForAll(
                Filter(
                    tbl_EntidadeContatoRelacionamento,
                    ID_emergencia = var_dadosEmergencia.ID && EndsWith(
                        Lower(email),
                        "@motiva.com.br"
                    )
                ),
                {
                    ID_contato: ID_contato,
                    ID_entidade: ID_entidade,
                    Email: email,
                    Nome: nome,
                    Nivel: nivel
                }
            )
        );
        // C7 - operador só entra se tiver e-mail válido
        If(
            !IsBlank(varEmailUser) && "@" in varEmailUser,
            Collect(
                col_emailsCcrFilter,
                {
                    ID_contato: 0,
                    ID_entidade: 0,
                    Email: Lower(Trim(varEmailUser)),
                    Nome: varNomeUser,
                    Nivel: "OPERADOR"
                }
            )
        );
        // C1 - REMOVE DUPLICADOS PELO EMAIL
        // A versão anterior comparava o e-mail da linha com ele mesmo
        // dentro do LookUp (o escopo interno vencia o externo), então a
        // condição era sempre verdadeira, o LookUp devolvia sempre o 1º
        // contato e a coleção virava N cópias dele. Era isso que repetia
        // "Notificado via Flow" para a mesma pessoa e deixava os demais
        // participantes sem aviso nenhum.
        ClearCollect(
            col_emailsUnicos,
            ForAll(
                Distinct(
                    col_emailsCcrFilter,
                    Lower(Trim(Email))
                ) As EMAIL_UNICO,
                LookUp(
                    col_emailsCcrFilter,
                    Lower(Trim(Email)) = EMAIL_UNICO.Value
                )
            )
        );
        Clear(col_emailsCcrFilter);
        Collect(
            col_emailsCcrFilter,
            col_emailsUnicos
        );
        /*
        ClearCollect(
            col_emailsCcrFilter;
            ShowColumns(
                Filter(
                    tbl_EntidadeContatoRelacionamento;
                    ID_emergencia = var_dadosEmergencia.ID && EndsWith(
                        Lower(email);
                        "@motiva.com.br"
                    )
                );
                ID_entidade;
                ID_contato;
                email;
                nivel;
                nome
            )
        );;
        // adiciona operador
        Collect(
            col_emailsCcrFilter;
            {
                ID_contato: 0;
                ID_entidade: 0;
                Email: varEmailUser;
                Nome: varNomeUser;
                Nivel: "OPERADOR"
            }
        );;*///---------------------------------------------------------
        // VALIDA PARTICIPANTES
        //---------------------------------------------------------
        If(
            CountRows(
                Filter(
                    col_emailsCcrFilter,
                    Nivel <> "OPERADOR"
                )
            ) = 0,
            // C2 - antes o teste era CountRows(col) = 0, mas o operador já
            // tinha sido inserido acima: nunca dava 0 e a validação era
            // letra morta. E, ao abortar, o overlay de carregamento ficava
            // aberto para sempre (tela travada).
            Notify(
                "Nenhum participante encontrado para esta emergência neste aeroporto. Revise o fluxograma de acionamento antes de iniciar.",
                NotificationType.Error,
                8000
            );
            UpdateContext(
                {
                    var_visibleConfigFluxo: false,
                    var_ocupadoDesde: Blank()
                }
            ),
            //-----------------------------------------------------
// GERA JSON PARTICIPANTES
//-----------------------------------------------------
            // C9 - o operador NÃO entra na lista de membros do chat: o Teams
            // cria o chat com a conexão dele e já o inclui como criador.
            // Mandá-lo junto devolve "Duplicate chat members is specified
            // in the request body" e o chat não é criado.
            // Ele continua na coleção para receber a notificação e
            // aparecer no log de NOTIFICADO.
            Set(
                JSON_PARTICIPANTES,
                JSON(
                    Filter(
                        col_emailsCcrFilter,
                        Nivel <> "OPERADOR"
                    ),
                    JSONFormat.Compact
                )
            );
            //-----------------------------------------------------
            // CRIA CHAT TEAMS
            //-----------------------------------------------------
            Set(
                var_retornoFluxoChat,
                'CriarchatdeacionamentosPLEM/PRAI'.Run(
                    JSON_PARTICIPANTES,
                    Coalesce(
                        _registro.Emergencia,
                        "Emergência não informada"
                    ),
                    Coalesce(
                        _registro.Ambiente,
                        "Ambiente Real"
                    ),
                    Coalesce(
                        _registro.Usuario,
                        varNomeUser,
                        "-"
                    ),
                    Coalesce(
                        _aeroporto,
                        varAeroUser,
                        "-"
                    ),
                    Coalesce(
                        _registro.Descricao_da_ocorrencia,
                        "(sem descrição informada)"
                    ),
                    _registro.ID
                )
            );
            Set(
                varChatID,
                Trim(var_retornoFluxoChat.chat)
            );
            If(
                IsBlank(varChatID),
                Notify(
                    "Atenção: o chat do Teams não foi criado. As mensagens do acionamento não serão publicadas. Verifique o fluxo 'Criar chat de acionamentos PLEM/PRAI'.",
                    NotificationType.Warning
                )
            );
            //-----------------------------------------------------
            // SALVA ID CHAT
            //-----------------------------------------------------
            Patch(
                tbl_ocorrenciaAcionamento,
                _registro,
                {ID_chat: varChatID}
            );
            //-----------------------------------------------------
            // ENVIA NOTIFICAÇÃO PARTICIPANTES
            //-----------------------------------------------------
            ForAll(
                col_emailsCcrFilter As CONTATO,
                EnviarAcionamentocomOpcao.Run(
                    Coalesce(
                        CONTATO.Email,
                        "-"
                    ),
                    Coalesce(
                        _registro.Emergencia,
                        "Emergência não informada"
                    ),
                    Coalesce(
                        _registro.Ambiente,
                        "Ambiente Real"
                    ),
                    Coalesce(
                        _aeroporto,
                        varAeroUser,
                        "-"
                    ),
                    Coalesce(
                        _registro.Descricao_da_ocorrencia,
                        "(sem descrição informada)"
                    ),
                    _registro.ID,
                    // sem chat criado o fluxo ainda manda o e-mail e pede
                    // a resposta; só os posts no chat falham, e as ações
                    // seguintes toleram essa falha
                    Coalesce(
                        varChatID,
                        "-"
                    ),
                    Coalesce(
                        CONTATO.Nome,
                        CONTATO.Email,
                        "-"
                    ),
                    CONTATO.ID_entidade,
                    CONTATO.ID_contato,
                    Coalesce(
                        LookUp(
                            tbl_FluxogramaAcionamentos,
                            ID = CONTATO.ID_entidade
                        ).Titulo,
                        If(
                            CONTATO.Nivel = "OPERADOR",
                            "Operador do acionamento",
                            "Entidade não identificada"
                        )
                    )
                )
            );
            //-----------------------------------------------------
            // LOG CRIAÇÃO
            //-----------------------------------------------------
            Patch(
                tbl_atividadesPlemPrai,
                Defaults(tbl_atividadesPlemPrai),
                {
                    ID_acionamento: _registro.ID,
                    Acao: "CRIAÇÃO",
                    Atividade: "ACIONAMENTO ABERTO · " & _aeroporto & " — " & _registro.Emergencia & " · " & _registro.Ambiente,
                    // B2 - fim do hack de "-1 minuto": este log é gravado antes
                    // dos NOTIFICADO, então Now() já ordena certo por Hora
                    Hora: Now(),
                    ID_emergencia: var_dadosEmergencia.ID,
                    ID_chat: varChatID,
                    Ativo: 1
                }
            );
            //-----------------------------------------------------
            // LOG NOTIFICAÇÕES
            //-----------------------------------------------------
            ForAll(
                col_emailsCcrFilter As PARTICIPANTE,
                Patch(
                    tbl_atividadesPlemPrai,
                    Defaults(tbl_atividadesPlemPrai),
                    {
                        ID_acionamento: _registro.ID,
                        Acao: "NOTIFICADO",
                        Atividade: "NOTIFICADO · " & Coalesce(
                            LookUp(
                                tbl_FluxogramaAcionamentos,
                                ID = PARTICIPANTE.ID_entidade
                            ).Titulo,
                            If(
                                PARTICIPANTE.Nivel = "OPERADOR",
                                "Operador do acionamento",
                                "Entidade não identificada"
                            )
                        ) & " — " & PARTICIPANTE.Nome,
                        Hora: Now(),
                        ID_contato: PARTICIPANTE.ID_contato,
                        ID_entidade: PARTICIPANTE.ID_entidade,
                        ID_emergencia: var_dadosEmergencia.ID,
                        // B3 - sem Ativo o registro ficava nulo e os testes
                        // "Ativo = 0" dos botões nunca casavam
                        Ativo: 0,
                        ID_chat: varChatID
                    }
                )
            );
            //-----------------------------------------------------
            // FINALIZA UI
            //-----------------------------------------------------
            UpdateContext(
                {
                    var_visibleConfigFluxo: false,
                    var_ocupadoDesde: Blank(),
                    var_inicarTemp: true,
                    var_dadosAcionamento: LookUp(
                        tbl_ocorrenciaAcionamento,
                        ID = _registro.ID
                    ),
                    var_visibleFormOcorrenciaAcionamento: false,
                    var_visibleNovoAcionamento: false,
                    var_visibleFluxogramaAcionamentosReal: true,
                    var_viewAtividades: 1
                }
            );
            // Recarrega as atividades logo após criar o acionamento
            Select(Function_consultarAtividades)
        ),
            //-----------------------------------------------------
// LOG FINALIZAÇÃO
//-----------------------------------------------------
        // C3 - varChatID é global da sessão que CRIOU o acionamento; quem
        // finalizasse depois gravava chat em branco. M3 - o chat também
        // passa a ser avisado do encerramento.
        With(
            {
                _chatFinal: Coalesce(
                    _registro.ID_chat,
                    var_dadosAcionamento.ID_chat,
                    varChatID
                )
            },
            Patch(
                tbl_atividadesPlemPrai,
                Defaults(tbl_atividadesPlemPrai),
                {
                    ID_acionamento: _registro.ID,
                    Acao: "FINALIZAÇÃO",
                    Atividade: "ACIONAMENTO ENCERRADO · " & _aeroporto & " — " & _registro.Emergencia,
                    Hora: Now(),
                    Ativo: 1,
                    ID_chat: _chatFinal
                }
            );
            If(
                !IsBlank(_chatFinal),
                EnviarAtividadeparachatteams.Run(
                    "ENCERRADO§" & _aeroporto & " — " & _registro.Emergencia & "§Encerrado por " & varNomeUser & " em " & Text(
                        Now(),
                        DateTimeFormat.ShortDateTime
                    ),
                    _chatFinal
                )
            )
        );
        UpdateContext(
            {
                var_visibleFormOcorrenciaAcionamento: false,
                var_visibleFluxogramaAcionamentosReal: false,
                var_ocupadoDesde: Blank()
            }
        );
        Notify(
            "Fluxo de Acionamento finalizado com sucesso!",
            NotificationType.Success
        )
    )
)

